def _raise_on_missing_token(self, request):
    """Raise error on missing token."""
    if not request.token:
        raise InvalidRequestError(request=request,
                                  description='Missing token parameter.')

def _raise_on_unsupported_token(self, request):
    """Raise on unsupported tokens."""
    if request.token_type_hint and request.token_type_hint in self.valid_token_types:
        if request.token_type_hint not in self.supported_token_types:
            raise UnsupportedTokenTypeError(request=request)
